INSERT INTO claim_issues VALUES(67,'CHE','CHE 대인 압박 상대 Counter 프리셋','대인 압박 상대에게 롱볼 비중이 반복되면 빌드업 정본 유지 판정을 다시 본다.','대인 압박 상대 경기 3경기의 롱볼 비중(≥13%면 상대별 Counter 프리셋 검토).','matches',5,'league',NULL,NULL,NULL,'2026-10-21',1,'open','HELD','[유지] 기존 HELD 판정 묶음 — 재판정 조건을 트리거로 옮김(migration 115 백필)',NULL,'scripts/claim_issues.py --apply-watch watch.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21','watch','2026-10-21');
INSERT INTO claim_issues VALUES(68,'CHE','CHE 슬롯 확정: 파머–로저스·피벗 짝','CHE 슬롯이 확정되거나 바르코 실측이 생기면 파머–로저스 연계·라비아 피벗 짝 판정을 다시 본다.','로저스 CAM 슬롯 선발 시 파머와 CAM 유형 겹침(obs#464), 바르코 실측 생성 후 바르코 dlp ↔ 라비아 b2b/Ball-Winning 짝 정합성 재산출.','matches',3,'official',NULL,NULL,NULL,'2026-10-21',1,'open','HELD','[유지] 기존 HELD 판정 묶음 — 재판정 조건을 트리거로 옮김(migration 115 백필)',NULL,'scripts/claim_issues.py --apply-watch watch.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21','watch','2026-10-21');
INSERT INTO claim_issues VALUES(69,'CHE','경기 전용 프리셋 전·후반 분리(CHE 사례)','하프타임 교체·형태 변경으로 전·후반이 다른 경기가 반복되면 match_game_setups 경기당 1행 유지 판정을 다시 본다.','하프타임 다중 교체 + 형태 변경 경기 수, 전·후반 PPDA·점유·형태 차이.','matches',5,'league',NULL,NULL,NULL,'2026-10-21',1,'open','HELD','[유지] 기존 HELD 판정 묶음 — 재판정 조건을 트리거로 옮김(migration 115 백필)',NULL,'scripts/claim_issues.py --apply-watch watch.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21','watch','2026-10-21');
INSERT INTO claim_issues VALUES(70,'CHE','CHE 백3 vs 백4: 채택 이유·안정성','알론소가 백3 사유를 말하거나 백4 경기가 2경기 이상 쌓이면 백3 적합성 판정을 다시 본다.','백3/백4 경기 간 def_x·PPDA·실점 패턴, 윙백 배후 구역 상대 보유 셀 밀도, 상대 9번 유형별 백3/백4 선택.','matches',5,'official',NULL,NULL,NULL,'2026-10-21',1,'open','HELD','[유지] 기존 HELD 판정 묶음 — 재판정 조건을 트리거로 옮김(migration 115 백필)',NULL,'scripts/claim_issues.py --apply-watch watch.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21','watch','2026-10-21');
INSERT INTO claim_issues VALUES(71,'LIV','LIV 압박 구현 축(트리거·상대별·역할 조합)','FC27이 압박 트리거·상대별 압박 축을 주거나 역할 조합 A/B가 나오면 압박 한계 판정을 다시 본다.','game_system_changes(FC27)의 압박 트리거·상대별 압박 설정 여부, ST 포커스×DM/CM 포커스 조합 인게임 A/B 결과.','date',NULL,'official',NULL,NULL,'2026-12-31',NULL,1,'open','HELD','[유지] 기존 HELD 판정 묶음 — 재판정 조건을 트리거로 옮김(migration 115 백필)',NULL,'scripts/claim_issues.py --apply-watch watch.json, 2026-10-21','트리거는 verdict_note 산문 조건을 셀 수 있는 형태로 옮긴 것','2026-10-21','watch','2026-10-21');
